// T32：右栏“文稿”页。只从本案任务/成果索引选择 Markdown 来源，正文经 Host 的受控读取，
// 保存经 /api/documents/save 由服务生成来源任务的新草稿版本；本页不碰文件系统，也不缓存正文到浏览器存储。
import { MarkdownText } from '@deepseek-ai/dsh-client-ui-primitives'
import { useEffect, useRef, useState } from 'react'
import { OfficeDocumentPreview } from './document-preview.tsx'
import { Badge, Button, C, caseEvent, Empty, ErrorLine, Loading, Section, S, useCaseEvent, useLoad } from './kit.tsx'
import { WithCase, type SessionProps } from './session-case.tsx'
import { call, confirm, type CaseRef } from './state.ts'

interface Draft {
  title: string
  path: string
  version: number
}

interface Task {
  task_id: string
  status: string
  drafts: Draft[]
  finished_at: string | null
}

interface Output {
  title: string
  version: number
  task_id: string
  files: Array<{ format: 'md' | 'docx'; path: string }>
  confirmed_at: string
}

export type DocumentChoice = {
  kind: 'draft' | 'output'
  task_id: string
  title: string
  version: number
  path: string
  format: 'md' | 'docx'
  status?: string
  when: string | null
}

interface DocumentValue {
  task_id: string
  title: string
  version: number
  path: string
  text: string
}

interface SaveValue {
  task_id: string
  path: string
  version: number
  citation_check: unknown
  coverage: unknown
  not_fully_read: string[]
}

type ApiError = { code: string; message: string }
type SaveResult = { ok: true; value: SaveValue } | { ok: false; error: ApiError }
type ReadState =
  | { key: string; state: 'loading' }
  | { key: string; state: 'ok'; value: DocumentValue }
  | { key: string; state: 'fail'; error: ApiError }

type Editor = {
  key: string
  text: string
  savedText: string
}

const DOCUMENTS_CHANGED = 'lawbench:documents-changed'
const SAVE_OPERATIONS_CHANGED = 'lawbench:document-save-operations-changed'
const documentKey = (caseId: string, path: string): string => `${caseId}\n${path}`
const MAX_EDITOR_BYTES = 512 * 1024
type PendingDocument = { caseId: string; path: string; text: string; savedText: string }
type SessionDocuments = { lastKey?: string; items: Map<string, PendingDocument> }
type SaveOperation = {
  id: string
  key: string
  sessionId?: string
  caseId: string
  documentKey: string
  path: string
  content: string
  status: 'pending' | 'success' | 'error'
  result?: SaveResult
}

/** 页签关闭、换案和会话切换共用这份进程内暂存；每份文稿各占一项，互不清空。 */
const pendingDocuments = new Map<string, SessionDocuments>()
const activeDocuments = new Map<string, () => void>()
const saveOperations = new Map<string, SaveOperation>()
let saveSequence = 0

function saveOperationKey(sessionId: string | undefined, key: string): string {
  return `${sessionId ?? ''}\n${key}`
}

function notifySaveOperations(): void {
  window.dispatchEvent(new CustomEvent(SAVE_OPERATIONS_CHANGED))
}

function rememberPendingDocument(sessionId: string, document: PendingDocument): void {
  let session = pendingDocuments.get(sessionId)
  if (!session) {
    session = { items: new Map() }
    pendingDocuments.set(sessionId, session)
  }
  const key = documentKey(document.caseId, document.path)
  session.items.set(key, document)
  session.lastKey = key
}

function pendingDocument(sessionId: string | undefined, caseId: string, path: string): PendingDocument | undefined {
  return sessionId ? pendingDocuments.get(sessionId)?.items.get(documentKey(caseId, path)) : undefined
}

function forgetPendingDocument(sessionId: string | undefined, caseId: string, path: string): void {
  if (!sessionId) return
  const session = pendingDocuments.get(sessionId)
  if (!session) return
  const key = documentKey(caseId, path)
  session.items.delete(key)
  if (session.lastKey === key) session.lastKey = [...session.items.keys()].at(-1)
  if (!session.items.size) pendingDocuments.delete(sessionId)
}

function settleSaveOperation(operation: SaveOperation): void {
  if (saveOperations.get(operation.key) === operation) saveOperations.delete(operation.key)
  notifySaveOperations()
}

function beginSaveOperation(args: {
  sessionId?: string
  caseId: string
  documentKey: string
  path: string
  content: string
}): SaveOperation {
  const key = saveOperationKey(args.sessionId, args.documentKey)
  const existing = saveOperations.get(key)
  if (existing) return existing
  const operation: SaveOperation = {
    id: String(++saveSequence),
    key,
    ...args,
    status: 'pending',
  }
  saveOperations.set(key, operation)
  notifySaveOperations()
  void call<SaveValue>('documentsSave', { case_id: args.caseId, path: args.path, content: args.content })
    .then((result) => {
      operation.status = result.ok ? 'success' : 'error'
      operation.result = result
      if (result.ok) {
        forgetPendingDocument(args.sessionId, args.caseId, args.path)
        caseEvent(DOCUMENTS_CHANGED, args.caseId)
        caseEvent('lawbench:tasks-changed', args.caseId)
      }
      notifySaveOperations()
    })
  return operation
}

export function captureDocumentsBeforeClose(sessionId: string): void {
  activeDocuments.get(sessionId)?.()
}

/** textarea 的 DOM value 固定把 CRLF 变成 LF；以紧前正文为基准，未变的相邻行沿用旧分隔符，只给新边界选默认值。 */
export function preserveLineEndings(value: string, reference: string): string {
  const oldEnds = reference.match(/\r\n|\r|\n/g) ?? []
  const oldParts = reference.split(/\r\n|\r|\n/)
  const parts = value.split(/\r\n|\r|\n/)
  const newEnds = value.match(/\r\n|\r|\n/g) ?? []
  if (!newEnds.length) return value

  const newToOld = new Array<number | undefined>(parts.length)
  let prefix = 0
  while (prefix < oldParts.length && prefix < parts.length && oldParts[prefix] === parts[prefix]) {
    newToOld[prefix] = prefix
    prefix++
  }
  let oldSuffix = oldParts.length - 1
  let newSuffix = parts.length - 1
  while (oldSuffix >= prefix && newSuffix >= prefix && oldParts[oldSuffix] === parts[newSuffix]) {
    newToOld[newSuffix] = oldSuffix
    oldSuffix--
    newSuffix--
  }
  if (oldParts.length === parts.length) {
    for (let i = prefix; i <= newSuffix; i++) newToOld[i] = i
  }

  const crlf = (reference.match(/\r\n/g) ?? []).length
  const lf = (reference.match(/(?<!\r)\n/g) ?? []).length
  const cr = (reference.match(/\r(?!\n)/g) ?? []).length
  const fallback = !oldEnds.length ? '\n' : crlf >= lf && crlf >= cr ? '\r\n' : lf >= cr ? '\n' : '\r'
  let preserved = ''
  for (let i = 0; i < newEnds.length; i++) {
    const oldLeft = newToOld[i]
    const oldRight = newToOld[i + 1]
    const separator = oldLeft !== undefined && oldRight === oldLeft + 1 ? oldEnds[oldLeft] : fallback
    preserved += parts[i] + separator
  }
  return preserved + parts[parts.length - 1]
}

/** 任务草稿和已确认成果里的 Markdown 都明确列出；不从文件名或全部历史里猜“最新”。 */
export function documentChoices(tasks: readonly Task[], outputs: readonly Output[]): DocumentChoice[] {
  const drafts = tasks.flatMap((task) => task.drafts.map((draft) => ({
    kind: 'draft' as const,
    task_id: task.task_id,
    title: draft.title,
    version: draft.version,
    path: draft.path,
    format: 'md' as const,
    status: task.status,
    when: task.finished_at,
  })))
  const results = outputs.flatMap((output) => output.files
    .filter((file) => file.format === 'md' || file.format === 'docx')
    .map((file) => ({
      kind: 'output' as const,
      task_id: output.task_id,
      title: output.title,
      version: output.version,
      path: file.path,
      format: file.format,
      when: output.confirmed_at,
    })))
  return [...drafts, ...results]
}

async function loadChoices(caseId: string): Promise<
  { ok: true; value: { tasks: Task[]; outputs: Output[] } } | { ok: false; error: ApiError }
> {
  const [tasks, outputs] = await Promise.all([
    call<{ tasks: Task[] }>('tasksList', { case_id: caseId }),
    call<{ outputs: Output[] }>('outputsList', { case_id: caseId }),
  ])
  if (!tasks.ok) return tasks
  if (!outputs.ok) return outputs
  return { ok: true, value: { tasks: tasks.value.tasks, outputs: outputs.value.outputs } }
}

export function DocumentsTab(p: SessionProps) {
  return <WithCase p={p}>{(c) => <Documents caseRef={c} sessionId={p.sessionId} />}</WithCase>
}

/** 文稿页内容；导出给界面用例直接渲染。 */
export function Documents({ caseRef, sessionId }: { caseRef: CaseRef; sessionId?: string }) {
  const caseId = caseRef.case_id
  const [sources, reloadSources] = useLoad(() => loadChoices(caseId), [caseId])
  useCaseEvent(DOCUMENTS_CHANGED, caseId, reloadSources)

  // 选择连同案件编号保存；换案后旧选择自然失效，旧读取/保存响应也按 key 拒绝覆盖。
  const rememberedSession = sessionId ? pendingDocuments.get(sessionId) : undefined
  const remembered = rememberedSession?.lastKey ? rememberedSession.items.get(rememberedSession.lastKey) : undefined
  const [picked, setPicked] = useState<{ caseId: string; path: string } | undefined>(() =>
    remembered?.caseId === caseId ? { caseId, path: remembered.path } : undefined)
  const selected = picked?.caseId === caseId ? picked.path : undefined
  const [read, setRead] = useState<ReadState>()
  const [editor, setEditor] = useState<Editor>()
  const [mode, setMode] = useState<'preview' | 'edit'>('preview')
  const [saveError, setSaveError] = useState<ApiError>()
  const [savedMessage, setSavedMessage] = useState<string>()
  const [, refreshSaveOperations] = useState(0)

  const choices = sources.state === 'ok' ? documentChoices(sources.value.tasks, sources.value.outputs) : []
  const selectedChoice = choices.find((choice) => choice.path === selected)
  const key = selected ? documentKey(caseId, selected) : undefined
  const dirty = !!editor && editor.text !== editor.savedText
  const markdownSelected = selectedChoice?.format === 'md'
  const currentRead = markdownSelected ? read?.key === key ? read : key ? { key, state: 'loading' as const } : undefined : undefined
  const shownEditor = currentRead?.state === 'ok' && editor?.key === key ? editor : undefined
  const currentSaveOperation = key ? saveOperations.get(saveOperationKey(sessionId, key)) : undefined
  const saving = currentSaveOperation?.status === 'pending'

  useEffect(() => {
    const refresh = () => refreshSaveOperations((revision) => revision + 1)
    window.addEventListener(SAVE_OPERATIONS_CHANGED, refresh)
    return () => window.removeEventListener(SAVE_OPERATIONS_CHANGED, refresh)
  }, [])

  useEffect(() => {
    if (!selected || !markdownSelected) {
      setRead(undefined)
      setEditor(undefined)
      return
    }
    const myKey = documentKey(caseId, selected)
    let live = true
    setRead({ key: myKey, state: 'loading' })
    setEditor(undefined)
    setSaveError(undefined)
    void call<DocumentValue>('documentRead', { case_id: caseId, root: caseRef.root, path: selected }).then((r) => {
      if (!live) return
      if (!r.ok) {
        setRead({ key: myKey, state: 'fail', error: r.error })
        return
      }
      setRead({ key: myKey, state: 'ok', value: r.value })
      const kept = pendingDocument(sessionId, caseId, selected)
      if (kept && kept.savedText !== r.value.text) forgetPendingDocument(sessionId, caseId, selected)
      const text = kept?.savedText === r.value.text ? kept.text : r.value.text
      setEditor({ key: myKey, text, savedText: r.value.text })
      setMode('preview')
    })
    return () => { live = false }
  }, [caseId, caseRef.root, markdownSelected, selected])

  const identity = sessionId && key ? `${sessionId}\n${key}` : undefined
  const live = useRef(new Map<string, { caseId: string; path: string; editor?: Editor }>())
  if (identity) live.current.set(identity, { caseId, path: selected!, editor })
  const discarded = useRef(new Set<string>())
  useEffect(() => {
    if (!sessionId || !identity) return
    const capture = () => {
      const current = live.current.get(identity)
      if (discarded.current.delete(identity)) {
        forgetPendingDocument(sessionId, caseId, selected!)
        return
      }
      if (!current?.editor || current.editor.text === current.editor.savedText) return
      rememberPendingDocument(sessionId, {
        caseId: current.caseId,
        path: current.path,
        text: current.editor.text,
        savedText: current.editor.savedText,
      })
    }
    activeDocuments.set(sessionId, capture)
    return () => {
      capture()
      if (activeDocuments.get(sessionId) === capture) activeDocuments.delete(sessionId)
      live.current.delete(identity)
    }
  }, [caseId, identity, selected, sessionId])

  const handledSaveResults = useRef(new Set<string>())
  useEffect(() => {
    const operation = currentSaveOperation
    if (!operation || operation.status === 'pending' || handledSaveResults.current.has(operation.id)
      || currentRead?.state !== 'ok' || editor?.key !== key || !operation.result) return
    handledSaveResults.current.add(operation.id)
    const result = operation.result
    if (!result.ok) {
      setSaveError(result.error.code === 'TIMEOUT'
        ? { code: result.error.code, message: '保存结果不确定，本次没有自动重发。正文仍保留；请先重新打开原稿确认是否已生成新版本。' }
        : result.error)
      settleSaveOperation(operation)
      return
    }

    const nextKey = documentKey(caseId, result.value.path)
    const nextDocument: DocumentValue = {
      task_id: result.value.task_id,
      title: currentRead.value.title,
      version: result.value.version,
      path: result.value.path,
      text: operation.content,
    }
    setRead({ key: nextKey, state: 'ok', value: nextDocument })
    setEditor({ key: nextKey, text: operation.content, savedText: operation.content })
    setPicked({ caseId, path: result.value.path })
    setSavedMessage(`已保存为“${nextDocument.title}”第 ${result.value.version} 版`)
    if (sessionId) {
      // 保存成功后旧 identity 的 effect 清理不能再把已落盘正文记回旧版本缓存。
      discarded.current.add(`${sessionId}\n${operation.documentKey}`)
      forgetPendingDocument(sessionId, caseId, operation.path)
    }
    setMode('preview')
    settleSaveOperation(operation)
  }, [caseId, currentRead, currentSaveOperation, currentSaveOperation?.status, editor?.key, key, sessionId])

  const choose = async (choice: DocumentChoice) => {
    if (saving || choice.path === selected) return
    if (dirty && !await confirm('文稿还没保存', '切换文稿会放下这份尚未保存的修改。要继续吗？', '不保存并切换')) return
    if (dirty && sessionId && identity) {
      discarded.current.add(identity)
      forgetPendingDocument(sessionId, caseId, selected!)
    }
    setSaveError(undefined)
    setSavedMessage(undefined)
    setPicked({ caseId, path: choice.path })
  }

  const save = () => {
    if (!selected || !editor || currentRead?.state !== 'ok' || saving) return
    if (!editor.text.length) {
      setSaveError({ code: 'INVALID_ARGUMENT', message: '正文为空，不能保存。' })
      return
    }
    if (new TextEncoder().encode(editor.text).byteLength > MAX_EDITOR_BYTES) {
      setSaveError({ code: 'OUTPUT_TRUNCATED', message: '正文超过 512 KiB，不能保存为新版本；正文仍保留在这里。' })
      return
    }
    setSaveError(undefined)
    setSavedMessage(undefined)
    beginSaveOperation({
      sessionId,
      caseId,
      documentKey: editor.key,
      path: selected,
      content: editor.text,
    })
  }

  const draftChoices = choices.filter((choice) => choice.kind === 'draft')
  const outputChoices = choices.filter((choice) => choice.kind === 'output' && choice.format === 'md')
  const previewChoices = choices.filter((choice) => choice.kind === 'output' && choice.format === 'docx')

  return (
    <div style={S.pane}>
      <div>
        <div style={{ fontSize: 17, fontWeight: 600 }}>文稿</div>
        <div style={S.sub}>Markdown 保存会生成新草稿版本；已确认 DOCX 只生成只读预览，编辑交回 WPS/Office，二者都不覆盖原件。</div>
      </div>

      <Loading data={sources}>{(v) => {
        const all = documentChoices(v.tasks, v.outputs)
        if (!all.length) return <Empty>本案还没有可打开的草稿或已确认成果。</Empty>
        return (
          <>
            <ChoiceSection title="任务草稿" choices={draftChoices} selected={selected} disabled={saving} onChoose={choose} />
            <ChoiceSection title="已确认成果" choices={outputChoices} selected={selected} disabled={saving} onChoose={choose} />
            <ChoiceSection title="Word 成果预览" choices={previewChoices} selected={selected} disabled={saving} onChoose={choose} />
          </>
        )
      }}</Loading>

      {!selected ? <Empty>从上面选择一份文稿开始查看。</Empty> : (
        selectedChoice?.format === 'docx' ? (
          <OfficeDocumentPreview caseRef={caseRef} path={selectedChoice.path} title={selectedChoice.title} version={selectedChoice.version} />
        ) : (
        <Section title={selectedChoice ? `${selectedChoice.title} · 第 ${selectedChoice.version} 版` : '正在打开文稿'}
          extra={selectedChoice?.kind === 'draft' && selectedChoice.status === 'running'
            ? <Badge tone="warn">任务进行中，保存可能被拒</Badge>
            : <Badge tone={selectedChoice?.kind === 'output' ? 'ok' : 'info'}>{selectedChoice?.kind === 'output' ? '已确认成果' : '任务草稿'}</Badge>}>
          {currentRead?.state === 'loading' ? <Empty>读取完整正文中…</Empty> : null}
          {currentRead?.state === 'fail' ? <ErrorLine error={currentRead.error} /> : null}
          {currentRead?.state === 'ok' && shownEditor ? (
            <>
              <div style={S.sub}>{currentRead.value.path} · 读取时是第 {currentRead.value.version} 版</div>
              <div style={{ ...S.row, flexWrap: 'wrap' }}>
                <Button size="sm" variant={mode === 'preview' ? 'primary' : 'outline'} onClick={() => setMode('preview')}>预览</Button>
                <Button size="sm" variant={mode === 'edit' ? 'primary' : 'outline'} onClick={() => setMode('edit')}>编辑</Button>
                <Button size="sm" variant="primary" disabled={saving || !dirty || !shownEditor.text.length} onClick={() => void save()}>
                  {saving ? '保存中…' : '保存为新草稿版本'}
                </Button>
                <span style={{ ...S.sub, color: dirty ? C.warn : C.sub }}>{dirty ? '有未保存的修改' : '没有未保存的修改'}</span>
              </div>
              {mode === 'edit'
                ? <textarea aria-label="Markdown 正文" value={shownEditor.text} disabled={saving}
                    onChange={(e) => setEditor({ ...shownEditor, text: preserveLineEndings(e.target.value, shownEditor.text) })}
                    style={{ ...S.input, width: '100%', minHeight: 320, boxSizing: 'border-box', resize: 'vertical', lineHeight: 1.6, fontFamily: 'inherit' }} />
                : <div style={{ ...S.card, minHeight: 160, overflowWrap: 'anywhere' }}><MarkdownText text={shownEditor.text}
                    labels={{ code: { copyLabel: '复制', copiedLabel: '已复制' }, footnotes: '注释' }} /></div>}
              <ErrorLine error={saveError} />
              {savedMessage ? <div role="status" style={{ color: C.ok, fontSize: 12 }}>{savedMessage}</div> : null}
            </>
          ) : null}
        </Section>
        )
      )}
    </div>
  )
}

function ChoiceSection({ title, choices, selected, disabled, onChoose }: {
  title: string
  choices: DocumentChoice[]
  selected?: string
  disabled: boolean
  onChoose: (choice: DocumentChoice) => void
}) {
  if (!choices.length) return null
  return (
    <Section title={title}>
      <ul style={S.list}>{choices.map((choice) => (
        <li key={`${choice.kind}\n${choice.path}`}>
          <Button size="sm" variant={choice.path === selected ? 'primary' : 'ghost'} disabled={disabled} aria-pressed={choice.path === selected}
            style={{ width: '100%', justifyContent: 'flex-start', textAlign: 'left', whiteSpace: 'normal' }} onClick={() => onChoose(choice)}>
            {choice.title} · 第 {choice.version} 版{choice.format === 'docx' ? ' · DOCX 预览' : ''}
          </Button>
        </li>
      ))}</ul>
    </Section>
  )
}

// 输入区上方的任务结果（T14 派修 2，执行令 2026-10-03 15:41；用户原话件 OWNER-T14预算到顶对话区显示草稿-20261003-1549）：
// 到达用量上限那一轮，模型最后一次调用是"存草稿"、没写出文字回答，对话区只剩"已完成工作"，律师无处点出处。
// 这时在对话区（输入区上方）显示一句提示和刚存的草稿正文，正文用 DSH 的 MarkdownText 画，出处是可点按钮（同对话区的出处）。
// 草稿正文每次经 Host 的 taskAnswer 从案件里读（只读该任务目录），界面不留副本。成果页本轮不加草稿预览（候 owner N65）。
import { MarkdownText } from '@deepseek-ai/dsh-client-ui-primitives'
import { useMemo, useState } from 'react'
import { citationInlineMarks } from './citation.ts'
import { citationDepsFor } from './citation-deps.ts'
import { Button, C, getNav, Loading, useLoad } from './kit.tsx'
import { ResultCard } from './result-cards.tsx'
import { answerKind, app, call, hideTaskAnswer, notice, type AnswerKind, type CaseRef } from './state.ts'
import { useStore } from './store.ts'

export interface TaskAnswerView {
  status: string
  session_id: string | null
  used: number | null
  limit: number | null
  draft: { title: string; version: number; path: string; text: string; truncated: boolean } | null
}

/**
 * 提示那一句（纯函数，测试守着）。这块只在到达用量上限时出现（turnNotice 的 BUDGET_STOPPED、成果页里状态为到达上限的任务），
 * 所以第一句一律按到顶说，不看 result.json 的状态——它由 Agent 在一轮结束后异步写，界面可能读得比它早（T13 派修复核 F2）。
 * result.json 只用来取次数：用满写"已用完……（8/8）"；没用满（时间到，或用量还没写完）写"已到……用量上限（模型调用 5/8）"；取不到不写括号。
 */
export function answerNotice(v: Pick<TaskAnswerView, 'used' | 'limit' | 'draft'>, kind: AnswerKind = 'budget'): string {
  // 熔断第①道（注记 2026-10-14 19:01）：不说用量，说为什么停、请律师怎么做；有草稿同样说存了
  if (kind === 'repetition') return v.draft ? `${REPETITION_TEXT}；已把做到的部分存为草稿` : REPETITION_TEXT
  const known = v.used !== null && v.limit !== null
  const head = known && v.used! >= v.limit! ? `已用完本次运行的模型调用次数（${v.used}/${v.limit}）`
    : known ? `已到本次运行的用量上限（模型调用 ${v.used}/${v.limit}）` : '已到本次运行的用量上限'
  // 令 0321：有草稿（模型自己存的，或到顶时代存的"未完成"草稿）说"已把做到的部分存为草稿"；没有任何文字可存时照旧
  return v.draft ? `${head}，已把做到的部分存为草稿` : `${head}，没有存下草稿；做到哪里请看成果里的"未完成"`
}

/** 到顶后点"继续"在同一对话里替律师发的那句（注记 1616 第 5 条，B 定的口径：服务会把上个任务的读取记录带进来）。 */
export const CONTINUE_TEXT = '接着上次没做完的继续，先看已存的草稿'

/** 思考 / 回复原样重复、模型调用被中止（Agent 插件 REPETITION_STOPPED）。与 agent\index.ts 的 REPETITION_MESSAGE 同一句。 */
export const REPETITION_TEXT = '这个请求我做不了或没理解，请换个说法或拆成小步'

/** 到顶时由 Agent 插件代存的草稿（标题以"（未完成）"结尾，同 agent\task-state.ts 的 UNFINISHED_SUFFIX）。 */
export const isUnfinished = (title: string): boolean => title.endsWith('（未完成）')

const LABELS = { code: { copyLabel: '复制', copiedLabel: '已复制' }, footnotes: '注释' }

/** 某会话输入区上方的任务结果；没有要显示的为空。 */
export function TaskAnswerSlot({ caseRef, sessionId }: { caseRef: CaseRef; sessionId: string }) {
  const taskId = useStore(app, (s) => s.answers[sessionId])
  if (!taskId) return null
  return <TaskAnswerPanel key={taskId} caseRef={caseRef} sessionId={sessionId} taskId={taskId} />
}

function TaskAnswerPanel({ caseRef, sessionId, taskId }: { caseRef: CaseRef; sessionId: string; taskId: string }) {
  const [data] = useLoad(() => call<TaskAnswerView>('taskAnswer', { root: caseRef.root, task_id: taskId }), [caseRef.root, taskId])
  const marks = useMemo(() => citationInlineMarks(citationDepsFor(taskId)), [taskId])
  const kind = answerKind(sessionId)
  const running = useStore(app, (s) => s.runningSessions.includes(sessionId))
  const [sending, setSending] = useState(false)
  // 到顶才有"继续"（熔断是没理解，接着做没有用）；一轮还在跑、正在发时不能点；发出去了就收起这块
  const goOn = async () => {
    setSending(true)
    const sent = await getNav().sendMessage?.(sessionId, CONTINUE_TEXT).catch(() => false)
    setSending(false)
    if (sent) hideTaskAnswer(sessionId); else notice('没有发出去', '请在输入框里自己发一句"继续"。')
  }
  return (
    <section aria-label="本次运行的结果" style={{ border: `1px solid ${C.warn}`, borderRadius: C.rMd, padding: '6px 10px', margin: '0 0 6px', fontSize: 13, color: C.text, maxHeight: '45vh', overflow: 'auto' }}>
      <Loading data={data}>{(v) => (
        <>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', justifyContent: 'space-between' }}>
            <strong style={{ color: C.warn }}>{answerNotice(v, kind)}</strong>
            <span style={{ display: 'flex', gap: 4, flexShrink: 0 }}>
              {kind === 'budget' ? <Button size="sm" variant="primary" style={{ whiteSpace: 'nowrap' }} disabled={running || sending} title={CONTINUE_TEXT} onClick={() => void goOn()}>继续</Button> : null}
              <Button size="sm" variant="ghost" style={{ whiteSpace: 'nowrap' }} onClick={() => hideTaskAnswer(sessionId)}>收起</Button>
            </span>
          </div>
          {v.draft ? (
            <>
              <div style={{ color: C.sub, fontSize: 12, margin: '4px 0' }}>草稿"{v.draft.title}"（第 {v.draft.version} 版）。点出处打开原文；到"成果"里确认保存、导出。</div>
              <MarkdownText text={v.draft.text} labels={LABELS} inlineMarks={marks} />
              {v.draft.truncated ? <div style={{ color: C.sub, fontSize: 12 }}>草稿较长，这里只显示前一部分。</div> : null}
              {/* 到顶时代存的草稿不是模型调工具存的，聊天流里没有它的卡片：在这里放一张，可以确认保存、选作下一步输入 */}
              {isUnfinished(v.draft.title) ? <ResultCard caseRef={caseRef} sessionId={sessionId} draft={{ seq: 0, title: v.draft.title, path: v.draft.path, version: v.draft.version, coverage: null, citation_check: null }} /> : null}
            </>
          ) : null}
        </>
      )}</Loading>
    </section>
  )
}

// 草稿正文里的出处（T13 后续项"点出处打开原文"）的纯逻辑：识别、拆出每一处、核对后打开。
// T17 第二步 P-16 起，出处由 DSH 的 Markdown 渲染画成真按钮（ui-chat 的 chatInlineMarks 服务，我方只给正则、每处的范围和打开函数），
// 原来在 document 捕获阶段做命中测试的 citation-click.ts 撤掉。
// 出处写法以契约为准（contracts\common.schema.json 的 citation_text，formats.md 第 3 节），不另写更宽的规则；
// tests\citation.spec.ts 守着下面的 CITATION_PATTERN 与契约逐字一致。
// 出处文字来自模型的回答，当成不可信的输入：只拿去和材料列表比对，不拼进路径、不当成标记渲染。

/** 契约 citation_text 的 pattern 原文（带 ^…$）。1.4 起材料名里可带成对的〔…〕（N45）。 */
export const CITATION_PATTERN =
  '^〔(未找到依据|推断|(?:[^〔〕、 ]|〔[^〔〕、 ]*〕)+ (第[0-9]+(-[0-9]+)?[页段行]|[^〔〕、!]+![A-Z]{1,3}[0-9]+(:[A-Z]{1,3}[0-9]+)?)(、(?:[^〔〕、 ]|〔[^〔〕、 ]*〕)+ (第[0-9]+(-[0-9]+)?[页段行]|[^〔〕、!]+![A-Z]{1,3}[0-9]+(:[A-Z]{1,3}[0-9]+)?))*)〕$'

/** 在一段文字里找出处用的正则：契约 pattern 去掉首尾锚点。 */
export const citationScanner = (): RegExp => new RegExp(CITATION_PATTERN.slice(1, -1), 'g')

const FIXED = new Set(['未找到依据', '推断'])

export interface CitationItem {
  /** 这一处的原文，如"借款合同 第2页"。 */
  text: string
  name: string
  /** 位置部分，如"第2页"或"流水!B12"。 */
  loc: string
}

/**
 * 一个出处括号（契约写法的整段匹配，如"〔借款合同 第2页、流水!B12〕"）里每一处的起止（相对这段匹配）。
 * 〔未找到依据〕〔推断〕不是出处，返回空（不成按钮）。
 */
export function citationItemRanges(match: string): Array<[number, number]> {
  const inner = match.slice(1, -1)
  if (FIXED.has(inner)) return []
  const out: Array<[number, number]> = []
  let at = 1
  for (const part of inner.split('、')) {
    out.push([at, at + part.length])
    at += part.length + 1
  }
  return out
}

/** 一处出处的原文（如"借款合同 第2页"）拆成材料名和位置。 */
export function citationItem(text: string): CitationItem {
  const sp = text.indexOf(' ')
  return { text, name: text.slice(0, sp), loc: text.slice(sp + 1) }
}

export interface MaterialLite { material_id: string; name: string; unit: 'page' | 'para' | 'cell' | 'line'; unit_count: number; status: string }

const UNIT_OF: Record<string, MaterialLite['unit']> = { 页: 'page', 段: 'para', 行: 'line' }

/**
 * 按材料列表核对这一处出处。通过返回材料；不通过返回给律师看的中文说明（不打开，也不去猜别的材料）。
 */
export function resolveCitation(item: CitationItem, materials: readonly MaterialLite[]): { ok: true; material: MaterialLite } | { ok: false; message: string } {
  const same = materials.filter((m) => m.name === item.name)
  if (same.length === 0) return { ok: false, message: `本案材料里没有"${item.name}"，没法打开这处出处（可能材料改了名或出处写错了）。` }
  if (same.length > 1) return { ok: false, message: `本案有 ${same.length} 份材料都叫"${item.name}"，分不清是哪一份，没有打开。` }
  const m = same[0]!
  if (m.unit_count === 0) return { ok: false, message: `"${item.name}"没有可读的内容（可能解析失败），没法打开这处出处。` }
  const range = /^第([0-9]+)(?:-([0-9]+))?([页段行])$/.exec(item.loc)
  if (range) {
    const unit = UNIT_OF[range[3]!]!
    const from = Number(range[1]); const to = range[2] === undefined ? from : Number(range[2])
    if (unit !== m.unit) return { ok: false, message: `"${item.name}"按${{ page: '页', para: '段', line: '行', cell: '单元格' }[m.unit]}定位，出处写的是"${item.loc}"，对不上，没有打开。` }
    if (from < 1 || to < from || to > m.unit_count) return { ok: false, message: `"${item.name}"只有 ${m.unit_count} ${range[3]}，出处写的是"${item.loc}"，超出范围，没有打开。` }
  } else if (m.unit !== 'cell') {
    return { ok: false, message: `"${item.name}"不是表格，出处写的是"${item.loc}"，对不上，没有打开。` }
  }
  if (m.status === 'source_deleted') return { ok: false, message: `"${item.name}"的原件已经删除，没法打开原文。` }
  return { ok: true, material: m }
}

export interface OpenDeps {
  caseId(): string | undefined
  materials(caseId: string): Promise<MaterialLite[] | undefined>
  notice(title: string, text: string): void
  openSource(materialId: string, citation: string): void
}

/** 核对后打开原文；任何不通过都给中文提示，不静默、不打开（返修 B1：抽出来以便测试）。 */
export async function openCitation(item: CitationItem, deps: OpenDeps): Promise<void> {
  const caseId = deps.caseId()
  if (!caseId) { deps.notice('没有打开原文', '这个会话不在已打开的案件里。请从首页打开案件后再点出处。'); return }
  const ms = await deps.materials(caseId)
  if (!ms) { deps.notice('没有打开原文', '读不到本案材料列表，请稍后重试。'); return }
  if (deps.caseId() !== caseId) return // 读列表期间换了案件：这份列表和出处都属于原来的案件，不打开
  const v = resolveCitation(item, ms)
  if (!v.ok) { deps.notice('没有打开原文', v.message); return }
  deps.openSource(v.material.material_id, `〔${item.text}〕`)
}

/** 登记给 DSH 的出处标记（ui-chat 的 chatInlineMarks，P-16）：只给正则、每处的范围、读屏标签和打开函数，不给 HTML。 */
export interface CitationMark {
  pattern: RegExp
  ranges(match: string): Array<[number, number]>
  label(text: string): string
  open(text: string): void
}

/** 出处标记：点按钮（或 Tab 到后按 Enter）核对后打开原文，核对不过给中文提示。 */
export function citationMark(deps: OpenDeps): CitationMark {
  return {
    pattern: citationScanner(),
    ranges: citationItemRanges,
    label: (text) => `打开原文：${text}`,
    open: (text) => { void openCitation(citationItem(text), deps) },
  }
}

/** MarkdownText 的 inlineMarks 一段文字拆出的片段：原文或可点的出处。 */
export type InlinePart = string | { text: string; label: string; open: () => void }

/**
 * 我方自己用 DSH 的 MarkdownText 画文字时（对话区的草稿，T14 派修 2）给它的出处拆分：
 * 与 ui-chat 的 buildInlineMarks 同一算法，只一种标记（出处）。
 */
export function citationInlineMarks(deps: OpenDeps): { split(value: string): InlinePart[] | undefined } {
  const mark = citationMark(deps)
  return {
    split(value) {
      const spans: Array<{ start: number; end: number }> = []
      for (const m of value.matchAll(citationScanner())) {
        for (const [from, to] of mark.ranges(m[0])) spans.push({ start: m.index + from, end: m.index + to })
      }
      if (spans.length === 0) return undefined
      const out: InlinePart[] = []
      let at = 0
      for (const s of spans) {
        if (s.start > at) out.push(value.slice(at, s.start))
        const text = value.slice(s.start, s.end)
        out.push({ text, label: mark.label(text), open: () => mark.open(text) })
        at = s.end
      }
      if (at < value.length) out.push(value.slice(at))
      return out
    },
  }
}

// 出处点击用到的工作台状态：当前案件、材料列表、打开原文标签。对话区（DSH 的出处标记）和输入区上方的草稿（T14 派修 2）共用。
import { TABS } from './cases.ts'
import { getNav } from './kit.tsx'
import { app, call, currentCase, notice } from './state.ts'
import type { MaterialLite, OpenDeps } from './citation.ts'

/** 出处点击用到的工作台状态：当前案件、材料列表、打开原文标签。 */
export const citationDeps: OpenDeps = {
  caseId: () => currentCase(app.get())?.case_id,
  materials: async (caseId) => {
    const r = await call<{ materials: MaterialLite[] }>('materialsList', { case_id: caseId })
    return r.ok ? r.value.materials : undefined
  },
  notice,
  openSource: (materialId, citation) => getNav().openTab(TABS.source, { material_id: materialId, citation }),
}

/**
 * 从某个任务的草稿点出处（契约 1.4 `/api/source` 的 task_id）：带上任务编号，服务只按这个任务记的出处版本判断"原件已更新"，提示更准。
 * 对话区里的出处不知道属于哪个任务，仍用 citationDeps（不带）。
 */
export const citationDepsFor = (taskId: string): OpenDeps => ({
  ...citationDeps,
  openSource: (materialId, citation) => getNav().openTab(TABS.source, { material_id: materialId, citation, task_id: taskId }),
})

// 右侧栏"原文查看"标签（PRD 7.9；Spec 4.3 /api/source、/api/search）：按出处定位到页 / 段 / 行 / 单元格，
// PDF 另显示该页的页面图片（定位到页，不做文字高亮）。另带律师检索，点命中处即查看原文。
import { useEffect, useState, type FormEvent } from 'react'
import { errorText } from './format.ts'
import { Badge, Button, C, Empty, ErrorLine, S, Section } from './kit.tsx'
import { call, type CaseRef } from './state.ts'
import { WithCase, type SessionProps } from './session-case.tsx'

type Loc = { unit: 'page' | 'para' | 'line'; from: number; to?: number } | { unit: 'cell'; sheet: string; ref: string }
interface SourceView { name: string; loc: Loc; text: string; page_png_base64: string | null; source_changed: boolean }
interface Hit { name: string; material_id: string; citation: string; snippet: string; is_ocr: boolean; match: 'exact' | 'expanded' }

type TabInfo = { tab: { navigation: { params?: Record<string, unknown>; revision?: number } } }
type Props = SessionProps & { useTabInfo?: () => TabInfo }

const locText = (l: Loc) => l.unit === 'cell' ? `${l.sheet}!${l.ref}`
  : `第 ${l.from}${l.to && l.to !== l.from ? `-${l.to}` : ''} ${{ page: '页', para: '段', line: '行' }[l.unit]}`

export function SourceTab(p: Props) {
  const nav = p.useTabInfo?.().tab.navigation
  const params = (nav?.params ?? {}) as { material_id?: string; citation?: string; task_id?: string }
  return <WithCase p={p}>{(c) => <Source caseRef={c} initial={params.material_id && params.citation ? { material_id: params.material_id, citation: params.citation, ...(params.task_id ? { task_id: params.task_id } : {}) } : null} revision={nav?.revision ?? 0} />}</WithCase>
}

/** 要看的出处；task_id 是从哪个任务的草稿点进来的（契约 1.4，可没有）。 */
type Target = { material_id: string; citation: string; task_id?: string }

export function Source({ caseRef, initial, revision }: { caseRef: CaseRef; initial: Target | null; revision: number }) {
  const [target, setTarget] = useState<Target | null>(initial)
  const [view, setView] = useState<SourceView | null>(null)
  const [err, setErr] = useState<{ code: string; message: string } | null>(null)
  const [q, setQ] = useState('')
  const [hits, setHits] = useState<{ hits: Hit[]; total: number; truncated: boolean } | null>(null)

  useEffect(() => { if (initial) setTarget(initial) }, [revision, initial?.material_id, initial?.citation, initial?.task_id]) // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (!target) return
    let stop = false
    setView(null); setErr(null)
    void call<SourceView>('source', { case_id: caseRef.case_id, material_id: target.material_id, citation: target.citation, ...(target.task_id ? { task_id: target.task_id } : {}) }).then((r) => {
      if (stop) return
      if (r.ok) setView(r.value); else setErr(r.error)
    })
    return () => { stop = true }
  }, [caseRef.case_id, target?.material_id, target?.citation, target?.task_id]) // eslint-disable-line react-hooks/exhaustive-deps

  const search = async (e: FormEvent) => {
    e.preventDefault()
    const text = q.trim()
    if (!text) return
    const r = await call<{ hits: Hit[]; total: number; truncated: boolean }>('search', { case_id: caseRef.case_id, q: text.slice(0, 100) })
    if (r.ok) { setHits(r.value); setErr(null) } else setErr(r.error)
  }

  return (
    <div style={S.pane}>
      <form onSubmit={(e) => void search(e)} style={S.row}>
        <input style={{ ...S.input, flex: 1 }} value={q} maxLength={100} onChange={(e) => setQ(e.target.value)} placeholder="在本案材料里检索" aria-label="检索词" />
        <Button size="sm" variant="outline" type="submit">检索</Button>
      </form>
      {hits ? (
        <Section title={`检索结果（${hits.total} 处${hits.truncated ? '，只列出前面的' : ''}）`} extra={<Button size="sm" variant="ghost" onClick={() => setHits(null)}>收起</Button>}>
          {hits.hits.length === 0 ? <Empty>没有找到</Empty> : (
            <ul style={{ ...S.list, maxHeight: 220, overflow: 'auto' }}>{hits.hits.map((h, i) => (
              <li key={i}>
                <button type="button" onClick={() => setTarget({ material_id: h.material_id, citation: h.citation })}
                  style={{ ...S.card, padding: 6, width: '100%', textAlign: 'left', font: 'inherit', color: C.text, cursor: 'pointer' }}>
                  <div style={S.between}><span>{h.citation}</span><span style={S.row}>{h.is_ocr ? <Badge tone="warn">识别所得</Badge> : null}{h.match === 'expanded' ? <Badge tone="faint">近似</Badge> : null}</span></div>
                  <div style={S.sub}>…{h.snippet}…</div>
                </button>
              </li>
            ))}</ul>
          )}
        </Section>
      ) : null}
      <ErrorLine error={err ? { ...err, message: errorText(err) } : null} />
      {!target && !hits ? <Empty>点草稿或 wiki 建议里的出处，这里显示对应的原文；也可以在上面检索。</Empty> : null}
      {target && !view && !err ? <Empty>读取原文中…</Empty> : null}
      {view ? (
        <Section title={<span>{view.name} · {locText(view.loc)}</span>}>
          {view.source_changed ? <div style={{ color: C.warn, fontSize: 12 }}>原件在引用之后改过，下面是现在的内容，可能与当时不同。</div> : null}
          {view.page_png_base64 ? <img alt={`${view.name} ${locText(view.loc)} 的页面图片`} src={`data:image/png;base64,${view.page_png_base64}`} style={{ maxWidth: '100%', border: `1px solid ${C.border}`, borderRadius: C.rSm }} /> : null}
          <pre style={{ whiteSpace: 'pre-wrap', wordBreak: 'break-word', font: 'inherit', lineHeight: 1.7, margin: 0, ...S.card }}>{view.text}</pre>
        </Section>
      ) : null}
    </div>
  )
}

// 界面插件的共享状态：已登记的案件、会话 → 案件的对应、每个会话当前选的胶囊 / Skill / 参数 / 前序成果、
// 首页和成果区留给案件的"待带入意向"、弹框队列。
// 案件 = DSH 的工作区（Spec 1.2）：会话的工作目录就是案件文件夹。界面不接受、也不保存案件文件内容。
import type { CaseKind, FolderChoice, RegisteredKind } from '../shared/case-folders.ts'
import { REMOTE_METHODS } from '../shared/remote-methods.ts'
import type { ApiResult } from '../host/index.ts'
import { createStore } from './store.ts'
import { lawyerMessage } from './format.ts'
import type { MaterialBatch, MaterialBatchBlock, MaterialRoot } from './material-batch.ts'

/** last_opened：最近案件列表给的上次打开时间（首页卡片显示，令 1426）。 */
export interface CaseRef {
  case_id: string; name: string; root: string; exists?: boolean; last_opened?: string
  /** 案件类型（契约 1.4，服务回传；1.4 之前建的、没选过的为 null）。 */
  kind?: RegisteredKind | null
}

export interface Params { thinking: '关闭' | '低' | '中' | '高'; window: '32K' | '64K' | '128K'; max_tokens: number; temperature?: number }

/**
 * 会话输入区上方的选择（契约 1.2：服务管"当前选择"，界面显示前读、改动时写）。capsuleId 为 null 表示自由对话。
 * saved：这份选择是否已经和服务一致（刚从服务读回，或写成功之后没再改）；律师改动后为 false，直到写成功。
 */
export interface Selection { capsuleId: string | null; skill: string | null; params: Params | null; inputs: string[]; route: 'local' | 'external'; saved: boolean }

export type Dialog =
  | { kind: 'confirm'; title: string; text: string; ok: string; resolve: (yes: boolean) => void }
  | { kind: 'notice'; title: string; text: string; lines?: string[] }
  | { kind: 'import'; caseRef: CaseRef; paths: string[]; from: string; batchSessionId?: string; roots?: readonly MaterialRoot[] }
  | { kind: 'casePick'; then?: (c: CaseRef) => void }
  /** 设置有未保存的修改时离开：保存 / 不保存 / 取消（令 1609 第 2 条）。 */
  | { kind: 'unsaved'; title: string; text: string; resolve: (choice: 'save' | 'discard' | 'cancel') => void }
  /** 运行前有材料还没识别：去识别 / 仍然开始 / 取消（令 1257 第 1 条）。 */
  | { kind: 'ocrFirst'; title: string; text: string; resolve: (choice: 'ocr' | 'go' | 'cancel') => void }
  /** 新建案件选好文件夹后：要建哪些子文件夹（令 1852 第 17 条）；取消为 null（不新建）。 */
  | { kind: 'folders'; caseName: string; template: CaseKind; resolve: (choice: FolderChoice | null) => void }
  /** 首页空白处拖进文件夹：把它建成案件？选类型（令 1422）；取消为 null。 */
  | { kind: 'newCase'; name: string; resolve: (kind: 'civil' | 'criminal' | 'daily' | null) => void }

export interface AppState {
  cases: CaseRef[]
  /** 正有一轮在跑的会话（DSH 会话列表的 running；草稿卡片据此判断"产生这张草稿的那一轮"是不是还在进行，令 0405）。 */
  runningSessions: string[]
  /** 按会话 id（契约 1.2：服务的"当前选择"按会话存，界面同口径，T13 返修 P2-2）。 */
  selections: Record<string, Selection>
  /** 按案件 id：首页点胶囊、成果区"选用"留下的改动，由该案件当前会话的输入区读回服务的选择后取走一次。 */
  intents: Record<string, Intent>
  /**
   * 按会话 id：上一轮因输入材料变化被拦下（/core/context 报 INPUT_CHANGED），状态行提示重新选择，律师改动选择后消失。
   * 放在 store 里，不放输入区组件里：换会话、插槽重挂都不丢（T13 INPUT_CHANGED 返修 P3-C ③）。
   */
  inputChanged: Record<string, true>
  /** 按会话 id：服务那份选择的输入快照已过期，下一次写入不能因"和服务那份一样"而省掉，写成才清（返修 P3-B）。 */
  staleServer: Record<string, true>
  dialogs: Dialog[]
  /** 设置里的默认参数（settings.json 的 defaults、skill_presets）；未读到时为 null。 */
  defaults: Params | null
  presets: Record<string, Params>
  /** DSH 当前显示的会话的工作目录（apply 里按 uiSession、sessions 更新）；没有会话为 null。 */
  currentRoot: string | null
  /**
   * 按会话 id：输入区上方要显示的任务结果（任务编号）。到达用量上限那一轮模型没写出回答，显示提示和刚存的草稿
   * （T14 派修 2，用户选"对话区显示草稿"）；成果页"在对话区查看"也写这里。只在内存，草稿正文每次从案件里读。
   */
  answers: Record<string, string>
  /** "日常事务"的位置（Host 的 dailyCase 取到后记下；令 1347：概览卡换成提示；"（非办案）"后缀已按注记 1653 去掉）；没有为 null。 */
  dailyRoot: string | null
  /** 日常事务建不了、且不会自己好时的说明（令 1347 一并做 P3-1，侧栏显示一行）；没有为 null。 */
  dailyError: { code: string; message: string } | null
  /** 设置里的本机律师姓名（首页右上角显示，令 1426）；没设为 null。 */
  lawyerName: string | null
  /** T31：输入区导入的下一问材料批次，按 DSH 会话留内存；每次发送只认当前会话和当前案件。 */
  materialBatches: Record<string, MaterialBatch>
  /** T31：导入已登记但本批未建立时的阻断态；律师取消或重新导入成功后消失。 */
  materialBatchBlocks: Record<string, MaterialBatchBlock>
}

export const app = createStore<AppState>({ cases: [], runningSessions: [], selections: {}, intents: {}, inputChanged: {}, staleServer: {}, dialogs: [], defaults: null, presets: {}, currentRoot: null, answers: {}, dailyRoot: null, dailyError: null, lawyerName: null, materialBatches: {}, materialBatchBlocks: {} })

/** 输入区上方那块"提示 + 草稿"是因为什么出现的：到达用量上限，或熔断第①道（思考 / 回复原样重复、这次调用被中止；注记 2026-10-14 19:01）。 */
export type AnswerKind = 'budget' | 'repetition'
const answerKinds = new Map<string, AnswerKind>()
export const answerKind = (sessionId: string): AnswerKind => answerKinds.get(sessionId) ?? 'budget'

/** 在某会话的输入区上方显示某任务的结果（T14 派修 2）。 */
export function showTaskAnswer(sessionId: string, taskId: string, kind: AnswerKind = 'budget'): void {
  answerKinds.set(sessionId, kind)
  app.set((s) => ({ ...s, answers: { ...s.answers, [sessionId]: taskId } }))
}

/** 收起某会话输入区上方的任务结果。 */
export function hideTaskAnswer(sessionId: string): void {
  answerKinds.delete(sessionId)
  app.set((s) => { const answers = { ...s.answers }; delete answers[sessionId]; return { ...s, answers } })
}

/** 当前会话对应的已登记案件。 */
export const currentCase = (s: AppState): CaseRef | undefined =>
  s.currentRoot ? s.cases.find((c) => samePath(c.root, s.currentRoot!)) : undefined

/** 案件显示名一律取文件夹名（令 1515 第 3 条：文件夹改名后显示跟着变；登记记录里的名字只作备用）。 */
export const folderName = (root: string): string => root.replace(/[\\/]+$/, '').split(/[\\/]/).pop() ?? ''

/** 这个案件是不是"日常事务"（令 1347）。 */
export const isDaily = (s: Pick<AppState, 'dailyRoot'>, c: Pick<CaseRef, 'root'> | undefined): boolean =>
  !!c && !!s.dailyRoot && samePath(c.root, s.dailyRoot)

/** 路径比较：不分大小写、正反斜杠一样、去掉末尾斜杠（Windows）。 */
export const samePath = (a: string, b: string): boolean => norm(a) === norm(b)
const norm = (p: string) => p.replace(/\//g, '\\').replace(/\\+$/, '').toLowerCase()

export const caseForRoot = (root: string | undefined): CaseRef | undefined =>
  root ? app.get().cases.find((c) => samePath(c.root, root)) : undefined

export function rememberCase(c: CaseRef): void {
  // 打开成功：放到案件表最前（从列表移除过的案件再次打开也回到这里，令 2125）
  app.set((s) => ({ ...s, cases: [c, ...s.cases.filter((x) => x.case_id !== c.case_id && !samePath(x.root, c.root))] }))
}

const EMPTY_SELECTION: Selection = { capsuleId: null, skill: null, params: null, inputs: [], route: 'local', saved: false }

/** 待带入意向：对选择的一次改动（字段同 Selection，没给的不改）。 */
export type Intent = Partial<Omit<Selection, 'saved'>>

/** 律师在输入区改动某会话的选择：记为未保存，输入区随后写给服务。 */
export function setSelection(sessionId: string, patch: Intent): void {
  app.set((s) => {
    const cur = s.selections[sessionId] ?? EMPTY_SELECTION
    return { ...s, selections: { ...s.selections, [sessionId]: { ...cur, ...patch, saved: false } } }
  })
}

/** 从服务读回的当前选择：原样显示，记为已保存。 */
export function applyServerSelection(sessionId: string, sel: Omit<Selection, 'saved'>): void {
  app.set((s) => ({ ...s, selections: { ...s.selections, [sessionId]: { ...sel, saved: true } } }))
}

/** 写成功：只有写的就是此刻显示的那份（写的途中没再改）才记为已保存。 */
export function markSelectionSaved(sessionId: string, isSame: (cur: Selection) => boolean): void {
  app.set((s) => {
    const cur = s.selections[sessionId]
    if (!cur || cur.saved || !isSame(cur)) return s
    return { ...s, selections: { ...s.selections, [sessionId]: { ...cur, saved: true } } }
  })
}

/** 首页点胶囊、成果区"选用"：给案件留一份待带入的改动（还没取走的与之合并，后给的字段覆盖先给的）。 */
export function setIntent(caseId: string, patch: Intent): void {
  app.set((s) => ({ ...s, intents: { ...s.intents, [caseId]: { ...s.intents[caseId], ...patch } } }))
}

/** 输入区取走案件的待带入意向（只取一次）；没有返回 undefined。 */
export function takeIntent(caseId: string): Intent | undefined {
  const it = app.get().intents[caseId]
  if (!it) return undefined
  app.set((s) => { const { [caseId]: _taken, ...rest } = s.intents; return { ...s, intents: rest } })
  return it
}

/** 收到 INPUT_CHANGED：该会话提示重新选择，服务那份记为需重写。 */
export function markInputChanged(sessionId: string): void {
  app.set((s) => ({ ...s, inputChanged: { ...s.inputChanged, [sessionId]: true }, staleServer: { ...s.staleServer, [sessionId]: true } }))
}

const without = (m: Record<string, true>, k: string): Record<string, true> => { const { [k]: _gone, ...rest } = m; return rest }

/** 律师改动了选择：提示消失（服务那份仍记为需重写，直到写成）。 */
export function clearInputChanged(sessionId: string): void {
  if (app.get().inputChanged[sessionId]) app.set((s) => ({ ...s, inputChanged: without(s.inputChanged, sessionId) }))
}

/** 写成了：服务那份重新有了当前的输入快照。 */
export function clearStaleServer(sessionId: string): void {
  if (app.get().staleServer[sessionId]) app.set((s) => ({ ...s, staleServer: without(s.staleServer, sessionId) }))
}

export function pushDialog(d: Dialog): void { app.set((s) => ({ ...s, dialogs: [...s.dialogs, d] })) }
export function popDialog(d: Dialog): void { app.set((s) => ({ ...s, dialogs: s.dialogs.filter((x) => x !== d) })) }

/** 弹确认框，律师点确定返回 true。所有发往服务器的操作都先经这里（工单第 3 步）。 */
export function confirm(title: string, text: string, ok = '确定'): Promise<boolean> {
  return new Promise((resolve) => pushDialog({ kind: 'confirm', title, text, ok, resolve }))
}

/** 首页空白处拖进文件夹时问"把它建成案件？"并选类型；取消为 null。 */
export function askNewCase(name: string): Promise<'civil' | 'criminal' | 'daily' | null> {
  return new Promise((resolve) => pushDialog({ kind: 'newCase', name, resolve }))
}

/** 新建案件时问要建哪些子文件夹（默认全不勾）；取消为 null。 */
export function askFolders(caseName: string, template: CaseKind): Promise<FolderChoice | null> {
  return new Promise((resolve) => pushDialog({ kind: 'folders', caseName, template, resolve }))
}

export function notice(title: string, text: string, lines?: string[]): void { pushDialog({ kind: 'notice', title, text, lines }) }

/** 测试连接一台服务器的结果（contracts\api\connection_test.schema.json）。 */
export interface ConnectionResult { reachable: boolean; key_valid: boolean | null; latency_ms: number | null; route: 'primary' | 'alternate' | null; message: string }

/** DSH 真正 credentials Remote 的配置态接口；没有读取秘密的路径。 */
export interface CredentialsApi {
  describe(refs: string[]): Promise<Record<string, { configured: boolean; source?: string; writable: boolean }>>
  set(ref: string, value: string): Promise<void>
  unset(ref: string): Promise<void>
}

/** DSH Gateway 对每次 Remote 调用的统一外壳。 */
export type RemoteResult<T> = { ok: true; value: T } | { ok: false; error?: { message?: string } }

/** DSH 真正 ctx.remote.credentials 的最小接口；没有读取秘密的方法。 */
export interface CredentialsRemote {
  describe(refs: string[]): Promise<RemoteResult<Record<string, { configured: boolean; source?: string; writable: boolean }>>>
  set(ref: string, value: string): Promise<RemoteResult<void>>
  unset(ref: string): Promise<RemoteResult<void>>
}

/** DSH 真实 settings Remote 的最小写面；只用于原子同步 llm-pi-ai 的外部 provider。 */
export interface SettingsRemote {
  mutate(ns: string, ops: Array<{ op: 'set' | 'unset'; path: string[]; value?: unknown }>, expectedRevision: number | undefined): Promise<RemoteResult<unknown>>
}

/** 界面调用 Host 的方法表（ctx.remote.lawbench），在 apply 里填入。 */
export type LawbenchApi = Record<string, (arg?: unknown) => Promise<ApiResult>> & {
  setupState(): Promise<{ configured: boolean; hasSettings: boolean; hasKey: boolean; service: string }>
  getSettings<T = Record<string, unknown>>(): Promise<T>
  putSettings(settings: unknown): Promise<unknown>
  changeKey(key: string): Promise<{ llm: ConnectionResult | null; prep: ConnectionResult | null; error: string | null }>
  listSkills(): Promise<{ ok: true; value: { skills: SkillInfo[] } }>
}

/** Skill 头部 mode 为对话型的取值（contracts\skill rontmatter.schema.json）。 */
export const MODE_AGENT = 'agent' as const // ui-words: 标识符（契约取值，不显示）

export interface SkillInfo {
  name: string; title: string; description: string; mode: 'agent' | 'pipeline'; kind: string // ui-words: 标识符（SKILL.md 头部 mode 的取值）
  params: Params; inputs: string[]; questions: { key: string; question: string; fromMaterials: boolean }[]
}

let api: LawbenchApi | undefined
const credentialsApiState = createStore<CredentialsApi | undefined>(undefined)
let settingsRemote: SettingsRemote | undefined

/**
 * DSH 网关的客户端把每次远程调用的返回再包一层 { ok, value }（失败为 { ok: false, error }，
 * packages/api/gateway/src/client/index.ts 的 invoke）。这里剥掉这一层：成功返回 Host 方法的原返回值，失败抛出。
 */
export function unwrapRemote(remote: Record<string, (...a: unknown[]) => Promise<unknown>>): LawbenchApi {
  return new Proxy({}, {
    get: (_t, method: string) => async (...args: unknown[]) => {
      const fn = remote[method]
      if (typeof fn !== 'function') throw new Error('工作台服务还没接上，请稍后重试')
      const r = (await fn.apply(remote, args)) as { ok: boolean; value?: unknown; error?: { message?: string } }
      if (!r || r.ok !== true) throw new Error(lawyerMessage(r?.error?.message))
      return r.value
    },
  }) as LawbenchApi
}

/** 剥掉 credentials Remote 的网关外壳；失败走调用点已有的固定提示。 */
export function unwrapCredentialsRemote(remote: CredentialsRemote): CredentialsApi {
  const value = async <T>(call: Promise<RemoteResult<T>>): Promise<T> => {
    const r = await call
    if (!r || r.ok !== true) throw new Error(lawyerMessage(r?.error?.message))
    return r.value
  }
  return {
    describe: (refs) => value(remote.describe(refs)),
    set: async (ref, secret) => { await value(remote.set(ref, secret)) },
    unset: async (ref) => { await value(remote.unset(ref)) },
  }
}

export const setApi = (a: LawbenchApi | undefined): void => { api = a }
export const currentLawbenchApi = (): LawbenchApi | undefined => api
export const setCredentialsApi = (a: CredentialsApi | undefined): void => { credentialsApiState.set(a) }
export const currentCredentialsApi = (): CredentialsApi | undefined => credentialsApiState.get()
export const subscribeCredentialsApi = credentialsApiState.subscribe
export const setSettingsRemote = (r: SettingsRemote | undefined): void => { settingsRemote = r }
export const currentSettingsRemote = (): SettingsRemote | undefined => settingsRemote
export const credentials = (): CredentialsApi => {
  const current = credentialsApiState.get()
  if (!current) throw new Error('凭据服务还没接上，请稍后重试')
  return current
}
export function lb(): LawbenchApi {
  if (!api) throw new Error('工作台服务还没接上，请稍后重试')
  return api
}

/** 调 /api 方法；失败返回 { ok: false }，界面按错误码显示（Q6）。Host 不可达也折成同样的形状。 */
export async function call<T = unknown>(
  method: string,
  request?: unknown,
  signal?: AbortSignal,
): Promise<{ ok: true; value: T } | { ok: false; error: { code: string; message: string } }> {
  try {
    // DSH 网关的客户端按方法表核对参数个数：没有参数的方法（selfCheck、dailyCase）多传一个 undefined 也会被拒
    // （"expected 0 argument(s), got 1"），启动检查提示条和日常事务都因此取不到（改版第 4 条真机截图时发现）
    const noArgs = REMOTE_METHODS.find((m) => m.method === method)?.params.length === 0
    const remote = lb()[method] as unknown as (...values: unknown[]) => Promise<unknown>
    // 仅调用方明确给 signal 时才增加尾随实参；原有无 signal 调用的实参个数完全不变。
    return (await (noArgs
      ? remote()
      : signal === undefined ? remote(request) : remote(request, signal))) as { ok: true; value: T }
  } catch (e) {
    return { ok: false, error: { code: 'SERVICE_UNAVAILABLE', message: lawyerMessage((e as Error)?.message) } }
  }
}

